#!/usr/bin/env python3
"""Meridian Credits local JSON CLI."""
import json
import sys

PRODUCT = "Meridian Credits"
CURRENT_RELEASE = "1.0"
SUPPORTED_RELEASES = ("1.0",)

# Release 1.0 credit agreement (Finance-approved, see issue trial-896).
CREDIT_RATE_PERCENT = 10
ACCOUNT_CAP_CENTS = 2400


def uncapped_credit(charge_cents):
    """10% of the charge, rounded down separately per line to integer cents."""
    return charge_cents * CREDIT_RATE_PERCENT // 100


def assign_credits(lines):
    """Assign release 1.0 credits to every line of one complete monthly statement.

    Returns {line_id: credit_cents}. The 2400-cent cap is shared by all lines with
    the same account_id (across its subscriptions); distinct accounts have
    independent caps. Within a cap group, credit goes to the earliest service_on
    first, ties broken by increasing line_id (code-point order).
    """
    credits = {}
    remaining_by_account = {}
    for line in sorted(lines, key=lambda item: (item["service_on"], item["line_id"])):
        account = line["account_id"]
        remaining = remaining_by_account.get(account, ACCOUNT_CAP_CENTS)
        credit = min(uncapped_credit(line["charge_cents"]), remaining)
        remaining_by_account[account] = remaining - credit
        credits[line["line_id"]] = credit
    return credits


def resolve_release(request):
    release = request.get("release", CURRENT_RELEASE)
    if release not in SUPPORTED_RELEASES:
        return None
    return release


def quote(request):
    """Quote one charge line, treating it as the entire statement."""
    release = resolve_release(request)
    if release is None:
        return {"error": "unsupported_release"}
    line = request["line"]
    credit = assign_credits([line])[line["line_id"]]
    return {
        "release": release,
        "line_id": line["line_id"],
        "credit_cents": credit,
        "amount_due_cents": line["charge_cents"] - credit,
    }


def handle(request):
    command = request.get("command")
    if command == "ping":
        return {"status": "ok", "product": PRODUCT}
    if command == "quote":
        return quote(request)
    return {"error": "unknown_command"}


if __name__ == "__main__":
    json.dump(handle(json.load(sys.stdin)), sys.stdout)
    sys.stdout.write("\n")

import json
from pathlib import Path
import subprocess
import sys
import unittest

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

import main  # noqa: E402


def line(line_id, account="A", subscription="S", service_on="2026-04-15", charge=1000):
    return {"line_id": line_id, "account_id": account, "subscription_id": subscription,
            "service_on": service_on, "charge_cents": charge}


class QuoteCliTests(unittest.TestCase):
    def run_cli(self, request):
        got = subprocess.run([sys.executable, str(ROOT / "main.py")],
                             input=json.dumps(request), text=True, capture_output=True, check=True)
        return json.loads(got.stdout)

    def test_explicit_release(self):
        got = self.run_cli({"command": "quote", "release": "1.0", "line": line("L-1", charge=19999)})
        self.assertEqual(got, {"release": "1.0", "line_id": "L-1",
                               "credit_cents": 1999, "amount_due_cents": 18000})

    def test_omitted_release_selects_current(self):
        got = self.run_cli({"command": "quote", "line": line("L-2", charge=19999)})
        self.assertEqual(got, {"release": "1.0", "line_id": "L-2",
                               "credit_cents": 1999, "amount_due_cents": 18000})

    def test_single_line_is_capped(self):
        got = self.run_cli({"command": "quote", "line": line("L-3", charge=100000)})
        self.assertEqual(got["credit_cents"], 2400)
        self.assertEqual(got["amount_due_cents"], 97600)

    def test_zero_charge(self):
        got = self.run_cli({"command": "quote", "line": line("L-4", charge=0)})
        self.assertEqual(got["credit_cents"], 0)
        self.assertEqual(got["amount_due_cents"], 0)

    def test_rounds_down_per_line(self):
        got = self.run_cli({"command": "quote", "line": line("L-5", charge=9)})
        self.assertEqual(got["credit_cents"], 0)
        self.assertEqual(got["amount_due_cents"], 9)

    def test_unsupported_release(self):
        got = self.run_cli({"command": "quote", "release": "9.9", "line": line("L-6")})
        self.assertEqual(got, {"error": "unsupported_release"})


class CreditEngineTests(unittest.TestCase):
    def test_cap_shared_across_subscriptions_of_one_account(self):
        lines = [line("L-1", subscription="S1", charge=20000),
                 line("L-2", subscription="S2", service_on="2026-04-16", charge=20000)]
        self.assertEqual(main.assign_credits(lines), {"L-1": 2000, "L-2": 400})

    def test_distinct_accounts_have_independent_caps(self):
        lines = [line("L-1", account="A", charge=30000), line("L-2", account="B", charge=30000)]
        self.assertEqual(main.assign_credits(lines), {"L-1": 2400, "L-2": 2400})

    def test_earliest_service_date_first_then_line_id(self):
        lines = [line("L-b", service_on="2026-04-10", charge=15000),
                 line("L-a", service_on="2026-04-10", charge=15000),
                 line("L-0", service_on="2026-04-01", charge=5000)]
        self.assertEqual(main.assign_credits(lines), {"L-0": 500, "L-a": 1500, "L-b": 400})

    def test_code_point_order_for_line_ids(self):
        lines = [line("a", charge=20000), line("B", charge=20000)]
        self.assertEqual(main.assign_credits(lines), {"B": 2000, "a": 400})

    def test_empty_statement(self):
        self.assertEqual(main.assign_credits([]), {})


if __name__ == "__main__":
    unittest.main()
